{"explanation": "Restore the dot check in hasCustomProtocol to treat protocols containing a dot as non-custom, ensuring they get normalized by prepending the default protocol.", "edits": [{"path": "index.js", "old": "const hasCustomProtocol = urlString => {
	try {
		const {protocol} = new URL(urlString);

		return protocol.endsWith(':')
			&& !supportedProtocols.has(protocol);
	} catch {
		return false;
	}
}", "new": "const hasCustomProtocol = urlString => {
	try {
		const {protocol} = new URL(urlString);

		return protocol.endsWith(':')
			&& !protocol.includes('.')
			&& !supportedProtocols.has(protocol);
	} catch {
		return false;
	}
}"}]}
